  color: var(--ink-muted);
}

.size-option.is-sold-out {
  cursor: not-allowed;
  background: var(--surface);
  color: var(--ink-muted);
}

.size-option.is-sold-out .size-us {
  text-decoration: line-through;
}

.sold-out {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--ink-muted);
}

/* Quantity */
.qty {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.qty-input {
  width: 4.5rem;
  height: 44px;
  text-align: center;
  font: inherit;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 0 0.5rem;
  -moz-appearance: textfield;
}

.qty-input::-webkit-outer-spin-button,
.qty-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.qty-input[aria-invalid='true'] {
  border: 2px solid var(--error);
}

.text-input {
  width: 100%;
  min-height: 44px;
  font: inherit;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.text-input[aria-invalid='true'] {
  border: 2px solid var(--error);
}

/* Buttons */
.actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.primary-btn,
.secondary-btn {
  min-height: 48px;
  padding: 0 1.5rem;
  border-radius: 999px;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.primary-btn {
  background: var(--accent);
  color: var(--accent-ink);
  border: 2px solid var(--accent);
  flex: 1 1 14rem;
}

.primary-btn:hover {
  background: #173b5e;
}

.primary-btn:disabled {
  background: var(--surface);
  color: var(--ink-muted);
  border-color: var(--line);
  cursor: not-allowed;
}

.secondary-btn {
  background: var(--paper);
  color: var(--ink);
  border: 2px solid var(--ink);
  flex: 1 1 12rem;
}

.secondary-btn[aria-pressed='true'] {
  background: var(--ink);
  color: var(--paper);
}

.status-stack {
  min-height: 1.5rem;
}

.cart-status,
.wish-status {
  color: var(--ink);
  font-weight: 600;
}

/* FAQ */
.faq {
  padding-top: 2rem;
  padding-bottom: 2rem;
  border-top: 1px solid #d9dce0;
}

.faq h2,
.more-info h2 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.faq-list {
  list-style: none;
  border-top: 1px solid #d9dce0;
}

.faq-item {
  border-bottom: 1px solid #d9dce0;
}

.faq-item h3 {
  font-size: 1rem;
}

.faq-button {
  width: 100%;
  min-height: 52px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 0;
  background: none;
  border: 0;
  font: inherit;
  font-weight: 600;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}

.faq-chevron {
  font-size: 1.5rem;
  line-height: 1;
}

.faq-answer {
  padding: 0 0 1rem;
  color: var(--ink-muted);
  max-width: 70ch;
}

.faq-answer[hidden] {
  display: none;
}

/* Tabs: More information */
.more-info {
  padding-top: 2rem;
  padding-bottom: 3rem;
  border-top: 1px solid #d9dce0;
}

.tablist {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border-bottom: 1px solid #c4c9cf;
}

.tab {
  min-height: 44px;
  padding: 0 1rem;
  background: none;
  border: 0;
  border-bottom: 3px solid transparent;
  margin-bottom: -1px;
  font: inherit;
  font-weight: 600;
  color: var(--ink-muted);
  cursor: pointer;
}

.tab[aria-selected='true'] {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.tabpanel {
  padding: 1.25rem 0;
  max-width: 70ch;
}

.tabpanel[hidden] {
  display: none;
}

.plain-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.review {
  padding-bottom: 0.75rem;
  border-bottom: 1px solid #e3e6ea;
}

.review time {
  color: var(--ink-muted);
  font-size: 0.875rem;
}

/* Size guide dialog */
.size-dialog {
  width: min(560px, calc(100vw - 2rem));
  max-height: calc(100vh - 2rem);
  padding: 0;
  border: 0;
  border-radius: 12px;
  color: var(--ink);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.size-dialog::backdrop {
  background: rgba(0, 0, 0, 0.55);
}

.size-dialog-body {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  padding: 1.5rem;
}

.size-dialog h2 {
  font-size: 1.5rem;
}

.system-options {
  display: flex;
  gap: 1rem;
}

.system-option {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 44px;
}

.system-option input {
  width: 20px;
  height: 20px;
  margin: 0;
}

.size-result {
  min-height: 1.5rem;
}

.result-text {
  font-size: 1.125rem;
  font-weight: 700;
}

.size-table {
  width: 100%;
  border-collapse: collapse;
}

.size-table caption {
  text-align: left;
  font-weight: 700;
  padding-bottom: 0.5rem;
}

.size-table th,
.size-table td {
  padding: 0.5rem;
  border-bottom: 1px solid #d9dce0;
  text-align: left;
}

.dialog-footer {
  display: flex;
  justify-content: flex-end;
}

/* Footer */
.site-footer {
  background: var(--surface);
  padding: 2.5rem 0 1rem;
  font-size: 0.9375rem;
}

.footer-grid {
  display: grid;
  gap: 2rem;
  grid-template-columns: 1fr;
}

@media (min-width: 700px) {
  .footer-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.site-footer h2 {
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.site-footer .plain-list {
  gap: 0.25rem;
}

.site-footer a {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
}

.social-list {
  list-style: none;
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.social-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--paper);
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
}

.copyright {
  margin-top: 2rem;
  color: var(--ink-muted);
  font-size: 0.875rem;
}

@media (prefers-reduced-motion: no-preference) {
  .primary-btn,
  .secondary-btn,
  .round-btn {
    transition: background-color 0.15s ease;
  }
}
