const visibleLabel = () => page.locator('.gallery-slide:not([hidden])').getAttribute('aria-label');
check('gallery starts at 1 of 3', (await visibleLabel()) === '1 of 3');
await page.getByRole('button', { name: 'Previous photo' }).click();
check('previous from first wraps to 3 of 3', (await visibleLabel()) === '3 of 3');
await page.getByRole('button', { name: 'Next photo' }).click();
check('next from last wraps to 1 of 3', (await visibleLabel()) === '1 of 3');
await page.getByRole('button', { name: 'Next photo' }).click();
check('next moves to 2 of 3', (await visibleLabel()) === '2 of 3');

