await page.getByRole('button', { name: 'About this price' }).hover();
check('tooltip shows on hover', await tip.isVisible());
check('tooltip text', (await tip.textContent()) === 'Price includes taxes.');
await page.keyboard.press('Escape');
check('Escape dismisses tooltip', !(await tip.isVisible()));
await page.mouse.move(5, 5);
await page.getByRole('button', { name: 'About this price' }).focus();
check('tooltip shows on focus', await tip.isVisible());
const desc = await page.getByRole('button', { name: 'About this price' }).getAttribute('aria-describedby');
check('button described by tooltip', desc && (await page.locator(`[id="${desc}"]`).textContent()) === 'Price includes taxes.');
await page.keyboard.press('Escape');
check('Escape dismisses focus tooltip', !(await tip.isVisible()));

// Color
check('only chosen color shown (Blue)', (await page.locator('.field-value').nth(0).textContent()) === 'Blue');
check('color swatches hidden before change', (await page.locator('.swatch').count()) === 0);
await page.getByRole('button', { name: 'Change color' }).click();
check('three color options', (await page.getByRole('radio', { name: /Blue|Black|Grey/ }).count()) === 3);
await page.getByRole('radio', { name: 'Black' }).click();
check('black color selected and list closed', (await page.locator('.field-value').nth(0).textContent()) === 'Black' && (await page.locator('.swatch').count()) === 0);
check('gallery shows black photo', (await page.locator('.gallery img').first().getAttribute('src')).includes('black'));
check('gallery resets to 1 of 3 on color change', (await visibleLabel()) === '1 of 3');
await page.getByRole('button', { name: 'Change color' }).click();
await page.getByRole('radio', { name: 'Grey' }).click();
check('grey selected', (await page.locator('.field-value').nth(0).textContent()) === 'Grey');

// Add to cart without size
await page.getByRole('button', { name: 'Add to cart' }).click();
check('error asks to pick size', (await page.locator('.error').first().textContent()).includes('Select a size'));
const focusedName = await page.evaluate(() => document.activeElement?.closest('label')?.textContent ?? document.activeElement?.outerHTML.slice(0,80));
check('focus moved to size list', (await page.evaluate(() => document.activeElement?.type)) === 'radio', focusedName);
check('cart still 0 after failed add', (await page.locator('.cart-count').textContent()) === '0');

// Sold-out size
const soldOut = page.getByRole('radio', { name: /US 7/ });
check('sold-out size disabled', await soldOut.isDisabled());
await page.getByRole('radio', { name: /US 9/ }).click();
check('size US 9 chosen, list closes', (await page.locator('.field-value').nth(1).textContent()).startsWith('US 9') && !(await page.getByRole('radio', { name: /US 9/ }).isVisible()));
check('error cleared after size chosen', (await page.locator('.error').count()) === 0);

// Quantity
const qty = page.locator('.qty-input');
await page.getByRole('button', { name: 'Increase quantity' }).click();
await page.getByRole('button', { name: 'Increase quantity' }).click();
check('qty increments to 3', (await qty.inputValue()) === '3');
await qty.fill('abc'); await qty.blur();
check('invalid qty error on blur', (await page.locator('.qty .error, .field .error').filter({ hasText: 'whole number' }).count()) === 1);
await qty.fill('0');
await page.getByRole('button', { name: 'Add to cart' }).click();
check('add with invalid qty does not add', (await page.locator('.cart-count').textContent()) === '0');
await qty.fill('2');
check('qty error clears when valid', (await page.locator('.error').filter({ hasText: 'whole number' }).count()) === 0);
await page.getByRole('button', { name: 'Decrease quantity' }).click();
check('qty decrements to 1', (await qty.inputValue()) === '1');
check('decrease disabled at min', await page.getByRole('button', { name: 'Decrease quantity' }).isDisabled());
await qty.fill('2');
await page.getByRole('button', { name: 'Add to cart' }).click();
check('cart count becomes 2', (await page.locator('.cart-count').textContent()) === '2');
check('cart status announced text', (await page.locator('.cart-status').textContent()).includes('Added 2 pairs of Trail Runner 2, Grey, US 9'));
check('header cart label', (await page.getByRole('link', { name: /Cart, 2 items/ }).count()) === 1);

// Wishlist
const wish = page.getByRole('button', { name: 'Save to wishlist' });
check('wishlist not pressed', (await wish.getAttribute('aria-pressed')) === 'false');
await wish.click();
check('wishlist pressed', (await wish.getAttribute('aria-pressed')) === 'true');
await wish.click();
check('wishlist unpressed', (await wish.getAttribute('aria-pressed')) === 'false');

// Size guide dialog
await page.getByRole('button', { name: 'Size guide' }).click();
const dlg = page.getByRole('dialog', { name: 'Size guide' });
check('size guide opens as modal', await dlg.isVisible());
await page.getByLabel('Foot length (cm)').fill('26');
check('foot 26 cm gives US 9', (await page.locator('.result-text').textContent()) === 'Your size is US 9.');
await page.getByRole('radio', { name: 'EU' }).check();
check('EU output', (await page.locator('.result-text').textContent()) === 'Your size is EU 42.');
await page.getByRole('radio', { name: 'US' }).check();
await page.getByRole('button', { name: 'Select US 9' }).click();
check('dialog closes after choosing size', !(await dlg.isVisible()));
check('size chosen from guide', (await page.locator('.field-value').nth(1).textContent()).startsWith('US 9'));
check('focus returns to size guide button', await page.evaluate(() => document.activeElement?.textContent === 'Size guide'));

await page.getByRole('button', { name: 'Size guide' }).click();
await page.getByLabel('Foot length (cm)').fill('27');
check('foot 27cm gives US 10', (await page.locator('.result-text').textContent()) === 'Your size is US 10.');
await page.getByLabel('Foot length (cm)').fill('31');
check('too long message', (await page.locator('.size-result').textContent()).includes('longer than our largest'));
await page.getByLabel('Foot length (cm)').fill('5');
check('invalid foot shows error', (await page.locator('.error').filter({ hasText: 'between 15 and 40' }).count()) === 1);
await page.getByLabel('Foot length (cm)').fill('25');
await page.keyboard.press('Escape');
check('Escape closes size guide', !(await dlg.isVisible()));

// Reviews/shipping tabs
const tabs = page.getByRole('tab');
await page.getByRole('tab', { name: 'Details' }).focus();
await page.keyboard.press('ArrowRight');
check('ArrowRight selects Reviews', (await page.getByRole('tab', { name: /Reviews/ }).getAttribute('aria-selected')) === 'true');
check('Reviews panel visible only', await page.getByRole('tabpanel', { name: /Reviews/ }).isVisible() && !(await page.getByRole('tabpanel', { name: 'Details' }).isVisible()));
await page.keyboard.press('End');
check('End selects Shipping', (await page.getByRole('tab', { name: 'Shipping & returns' }).getAttribute('aria-selected')) === 'true');
await page.keyboard.press('Home');
check('Home selects Details', (await page.getByRole('tab', { name: 'Details' }).getAttribute('aria-selected')) === 'true');
check('tabindex roving', (await page.getByRole('tab', { name: 'Reviews' }).getAttribute('tabindex')) === '-1');

// FAQ
const faq = page.getByRole('button', { name: 'Is Trail Runner 2 waterproof?' });
check('faq collapsed', (await faq.getAttribute('aria-expanded')) === 'false');
await faq.click();
check('faq expanded and answer visible', (await faq.getAttribute('aria-expanded')) === 'true' && (await page.getByText('water-resistant').isVisible()));
await faq.click();
check('faq collapses', !(await page.getByText('water-resistant').isVisible()));

// Footer
check('footer nav labels', (await page.getByRole('navigation', { name: 'Customer help' }).count()) === 1);
check('social links named', (await page.getByRole('link', { name: 'Stride on Instagram' }).count()) === 1);

// Axe WCAG 2.2 AA
const axe = await new AxeBuilder({ page }).withTags(['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']).analyze();
check('axe: no WCAG 2.2 AA violations (desktop, initial state)', axe.violations.length === 0, JSON.stringify(axe.violations.map(v => [v.id, v.nodes.length, v.nodes[0]?.html?.slice(0,120)])));

// Dialog open axe
await page.getByRole('button', { name: 'Size guide' }).click();
const axeDlg = await new AxeBuilder({ page }).withTags(['wcag2a','wcag2aa','wcag21aa','wcag22aa']).analyze();
check('axe: size guide dialog', axeDlg.violations.length === 0, JSON.stringify(axeDlg.violations.map(v => [v.id, v.nodes[0]?.html?.slice(0,120)])));
await page.keyboard.press('Escape');

// Mobile reflow at 320px
const m = await browser.newPage({ viewport: { width: 320, height: 800 } });
await m.goto(URL, { waitUntil: 'networkidle' });
const sw = await m.evaluate(() => document.documentElement.scrollWidth);
check('320px: no horizontal scroll', sw <= 320, 'scrollWidth=' + sw);
await m.screenshot({ path: '/tmp/e2e/mobile.png', fullPage: true });
const axeM = await new AxeBuilder({ page: m }).withTags(['wcag2aa','wcag22aa']).analyze();
check('axe: 320px', axeM.violations.length === 0, JSON.stringify(axeM.violations.map(v => v.id)));

// Keyboard: visible focus on a button
await page.keyboard.press('Tab');
await page.screenshot({ path: '/tmp/e2e/desktop-after.png', fullPage: false });

for (const r of results) console.log(r.join(' | '));
console.log('console errors/warnings:', errors);
await browser.close();
